import type { ProductImage } from "@/types/product";

/**
 * Every non-product image used across the site. Replace `src` with licensed or
 * original photography (keep width/height accurate to avoid layout shift).
 * Current files are original DEMO illustrations generated by scripts/generate-demo-media.ts.
 */
const demo = (file: string, alt: string, width: number, height: number): ProductImage => ({
  src: `/media/demo/${file}`,
  alt,
  width,
  height,
});

export const media = {
  hero: demo("hero-listening-room.svg", "A tall dark speaker standing in a dim architectural listening room, lit by a single shaft of light", 2400, 1400),
  heroMobile: demo("hero-listening-room-portrait.svg", "A tall dark speaker in a dim architectural listening room", 1000, 1500),
  intro: demo("driver-closeup.svg", "Close view of a speaker driver with a fine metallic surround", 1200, 1500),
  technology: demo("cabinet-section.svg", "Exploded view of a speaker cabinet showing drivers, port, and internal bracing", 1600, 1200),
  lifestyle: {
    living: demo("lifestyle-living-room.svg", "A pair of floor-standing speakers in a minimal living room at dusk", 1600, 1100),
    studio: demo("lifestyle-studio.svg", "Bookshelf monitors on a desk in a quiet studio", 1200, 1500),
    stage: demo("lifestyle-stage.svg", "Professional loudspeakers on a dark stage under a single wash of light", 1200, 1500),
  },
};
